<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElButton, ElAlert, ElDialog } from 'element-plus'
import { callAdmin, uploadAdminFile } from './api'
interface Banner { _id: string; image: string; link: string; sort: number; visible: boolean }
interface Announcement { _id: string; text: string; link: string; sort: number; visible: boolean }
interface Pick { productId: string; sort: number }
interface Product { _id: string; name: string; eligible: boolean }
const banners = ref<Banner[]>([]), announcements = ref<Announcement[]>([]), picks = ref<Pick[]>([]), products = ref<Product[]>([]), seconds = ref(5), tab = ref('banner'), busy = ref(false), error = ref(''), notice = ref(''), editor = ref(false)
const splash = ref({ enabled: false, image: '', link: '', seconds: 5 }), splashLinkPick = ref('')
const uploading = ref(''), uploadError = ref(''), uploadErrorFor = ref(''), pendingPick = ref('')
const form = ref({ id: '', image: '', text: '', link: '', sort: 0, visible: true, productId: '' })
const linkPick = ref('')
const title = computed(() => tab.value === 'banner' ? '轮播图' : tab.value === 'pick' ? '主推位' : tab.value === 'splash' ? '开屏广告' : '活动公告')
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function load() { const r = await callAdmin<{ banners: Banner[]; announcements: Announcement[]; picks: Pick[]; products: Product[]; seconds: number; splash: { enabled: boolean; image: string; link: string; seconds: number } }>('home.list'); banners.value = r.banners; announcements.value = r.announcements; picks.value = r.picks; products.value = r.products; seconds.value = r.seconds; splash.value = r.splash; splashLinkPick.value = r.splash.link.startsWith('/pages/product/index?id=') ? r.splash.link.slice('/pages/product/index?id='.length) : '' }
function open(item?: Banner | Announcement | Pick) { form.value = { id: item && '_id' in item ? item._id : item && 'productId' in item ? item.productId : '', image: item && 'image' in item ? item.image : '', text: item && 'text' in item ? item.text : '', link: item && 'link' in item ? item.link : '', sort: Number(item?.sort || 0), visible: item && 'visible' in item ? item.visible : true, productId: item && 'productId' in item ? item.productId : products.value.find(p => p.eligible)?._id || '' }; linkPick.value = form.value.link.startsWith('/pages/product/index?id=') ? form.value.link.slice('/pages/product/index?id='.length) : ''; editor.value = true }
function applyPick() { if (linkPick.value) form.value.link = '/pages/product/index?id=' + linkPick.value }
function save() { run(async () => { await callAdmin('home.' + tab.value + '.save', { id: tab.value === 'pick' ? form.value.productId : form.value.id || undefined, data: form.value }); editor.value = false; await load(); notice.value = '首页设置已保存' }) }
function remove(id: string) { if (confirm('确认删除这一项？')) run(async () => { await callAdmin('home.' + tab.value + '.delete', { id }); await load(); notice.value = '已删除' }) }
function applySplashPick() { if (splashLinkPick.value) splash.value.link = '/pages/product/index?id=' + splashLinkPick.value }
function saveSplash() { if (uploading.value === 'splash') { error.value = '图片正在上传，请等预览出现后再保存'; return } if (pendingPick.value === 'splash' && !splash.value.image) { error.value = '图片还没上传成功，请重新选图，等预览出现后再保存'; return } run(async () => { await callAdmin('home.splash.save', { data: { ...splash.value } }); notice.value = '开屏广告已保存' }) }
function doUpload(event: Event, which: string, apply: (url: string) => void) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; uploadError.value = ''; uploadErrorFor.value = which; if (file.size > 2097152) { uploadError.value = '图片超过2MB，请先压缩再传'; input.value = ''; return } if (which === 'splash') pendingPick.value = which; uploading.value = which; void (async () => { try { const res = await uploadAdminFile<{ url: string }>(file, { purpose: 'image' }); apply(res.url); if (pendingPick.value === which) pendingPick.value = ''; notice.value = '图片已上传，点保存后生效' } catch (e) { uploadError.value = e instanceof Error ? e.message : '图片上传失败，请重试' } finally { uploading.value = ''; input.value = '' } })() }
function splashUpload(event: Event) { doUpload(event, 'splash', url => { splash.value.image = url }) }
function upload(event: Event) { doUpload(event, 'form', url => { form.value.image = url }) }
onMounted(() => run(load))
</script>
<template><section class="content home-manager"><div class="section-heading"><div><p class="eyebrow">HOME OPERATIONS</p><h1>首页管理</h1></div><ElButton v-if="tab!=='splash'" type="primary" @click="open()">新增{{title}}</ElButton></div><ElAlert v-if="error" :title="error" type="error" :closable="false"/><ElAlert v-if="notice" :title="notice" type="success" :closable="false"/><div class="catalog-toolbar"><div class="tab-row"><button v-for="item in [{key:'banner',name:'轮播图'},{key:'pick',name:'主推位'},{key:'announcement',name:'活动公告'},{key:'splash',name:'开屏广告'}]" :key="item.key" :class="{active:tab===item.key}" @click="tab=item.key">{{item.name}}</button></div><ElButton @click="run(load)" :loading="busy">刷新首页配置</ElButton></div>
<template v-if="tab==='banner'"><article v-for="item in banners" :key="item._id" class="home-row" :data-home-id="item._id"><img :src="item.image" alt="轮播图"/><div><p>排序{{item.sort}} · {{item.visible?'显示':'隐藏'}}</p><p class="muted">{{item.link||'无跳转'}}</p></div><div class="action-row"><ElButton @click="open(item)">编辑</ElButton><ElButton @click="remove(item._id)">删除</ElButton></div></article></template>
<template v-else-if="tab==='pick'"><article v-for="item in picks" :key="item.productId" class="home-row" :data-home-id="item.productId"><div><h3>{{products.find(p=>p._id===item.productId)?.name||item.productId}}</h3><p>排序{{item.sort}} · {{products.find(p=>p._id===item.productId)?.eligible?'已审核上架':'当前不可见'}}</p></div><div class="action-row"><ElButton @click="open(item)">编辑</ElButton><ElButton @click="remove(item.productId)">删除</ElButton></div></article></template>
<template v-else-if="tab==='splash'"><form class="admin-form" @submit.prevent="saveSplash"><label class="checkbox-label"><input v-model="splash.enabled" type="checkbox" aria-label="启用开屏广告"/>启用开屏广告</label><label>广告图地址<input v-model="splash.image" aria-label="开屏广告图地址" placeholder="https://..."/></label><label>上传广告图<input type="file" accept="image/png,image/jpeg,image/webp" aria-label="上传开屏广告图" @change="splashUpload"/><span class="field-hint">居中弹窗展示，建议竖图，单张≤2MB；进小程序冷启动时弹出，后台切回不重复弹</span><span v-if="uploading==='splash'" class="field-hint">图片上传中…传完会自动出现地址，再点保存</span><span v-if="uploadError&&uploadErrorFor==='splash'" class="field-error">{{uploadError}}</span></label><label>点击跳转（可选）<input v-model="splash.link" aria-label="开屏跳转" placeholder="/pages/... 或 https://..."/></label><label>或选商品跳转<select v-model="splashLinkPick" aria-label="开屏选择跳转商品" @change="applySplashPick"><option value="">不选（用上方手填地址）</option><option v-for="p in products.filter(p=>p.eligible)" :key="p._id" :value="p._id">{{p.name}}</option></select></label><label>展示秒数（倒计时结束自动关闭，可手动跳过）<input v-model.number="splash.seconds" type="number" min="1" max="15" aria-label="开屏展示秒数"/></label><div class="form-footer"><ElButton native-type="submit" type="primary" :loading="busy" :disabled="uploading==='splash'">{{uploading==='splash'?'图片上传中…':'保存开屏广告'}}</ElButton></div></form></template>
<template v-else><form class="home-interval" @submit.prevent="run(async()=>{await callAdmin('home.interval',{data:{seconds}});notice='公告轮播间隔已保存'})"><label>公告轮播间隔（秒）<input v-model.number="seconds" type="number" min="1" max="60" aria-label="公告轮播间隔" :disabled="busy"/></label><ElButton native-type="submit" :loading="busy">保存轮播间隔</ElButton></form><article v-for="item in announcements" :key="item._id" class="home-row" :data-home-id="item._id"><div><h3>{{item.text}}</h3><p>排序{{item.sort}} · {{item.visible?'显示':'隐藏'}}</p><p class="muted">{{item.link||'无跳转'}}</p></div><div class="action-row"><ElButton @click="open(item)">编辑</ElButton><ElButton @click="remove(item._id)">删除</ElButton></div></article></template>
<ElDialog v-model="editor" :title="title+'资料'" width="min(560px, calc(100vw - 24px))"><ElAlert v-if="error" :title="error" type="error" :closable="false"/><form class="admin-form" @submit.prevent="save"><template v-if="tab==='banner'"><label>轮播图片地址<input v-model="form.image" aria-label="轮播图片地址" required/></label><label>上传轮播图片<input type="file" accept="image/png,image/jpeg,image/webp" aria-label="上传轮播图片" @change="upload"/><span class="field-hint">规格：约 1:1，建议 1080×1080，单张≤2MB</span></label></template><label v-if="tab==='announcement'">公告内容<textarea v-model="form.text" aria-label="公告内容" required maxlength="300"/></label><label v-if="tab==='pick'">主推商品<select v-model="form.productId" aria-label="主推商品"><option v-for="p in products.filter(p=>p.eligible)" :key="p._id" :value="p._id">{{p.name}}</option></select></label><label v-if="tab!=='pick'">跳转（可选）<input v-model="form.link" aria-label="首页跳转" placeholder="/pages/... 或 https://..."/></label><label v-if="tab!=='pick'">或选商品跳转<select v-model="linkPick" aria-label="选择跳转商品" @change="applyPick"><option value="">不选（用上方手填地址）</option><option v-for="p in products.filter(p=>p.eligible)" :key="p._id" :value="p._id">{{p.name}}</option></select></label><label>排序<input v-model.number="form.sort" aria-label="首页排序" type="number" min="0" max="100000"/></label><label v-if="tab!=='pick'" class="checkbox-label"><input v-model="form.visible" type="checkbox" aria-label="首页显示"/>显示</label><div class="form-footer"><ElButton @click="editor=false">取消</ElButton><ElButton native-type="submit" type="primary" :loading="busy">保存{{title}}</ElButton></div></form></ElDialog>
</section></template>
<style>
.field-hint{font-size:12px;color:#677185}
.field-error{font-size:12px;color:#c0392b;font-weight:600}
.home-row{display:flex;align-items:center;gap:20px;background:white;border:1px solid #e4e9f1;padding:20px;margin-bottom:14px;border-radius:8px}.home-row>div:not(.action-row){flex:1;min-width:0;overflow-wrap:anywhere}.home-row h3{font-size:16px;line-height:1.7;margin:0 0 8px}.home-row p{font-size:13px;line-height:1.7;margin:6px 0}.home-row img{width:130px;height:100px;object-fit:cover;border-radius:4px}.home-interval{display:flex;gap:16px;align-items:flex-end;background:white;padding:20px;margin-bottom:24px;border:1px solid #e4e9f1;border-radius:8px}.home-interval label{display:grid;gap:8px;font-size:13px}.home-interval input{width:120px;padding:10px;border:1px solid #dce2ec;border-radius:6px;font:inherit}@media(max-width:768px){.home-row{flex-wrap:wrap;gap:12px;padding:16px}.home-row img{width:86px;height:72px}.home-row .action-row{width:100%;justify-content:flex-end}.home-manager .section-heading{align-items:flex-start;gap:16px;flex-direction:column}.home-interval{flex-wrap:wrap;padding:16px}}
</style>
